def parser(log: str) -> dict[str, str]:
    import json
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def norm_status(value: str) -> str:
        v = value.lower()
        if v in {"pass", "passed", "ok", "success"}:
            return "pass"
        if v in {"skip", "skipped", "xfail", "xfailed", "notrun", "suppressed", "expected failure"}:
            return "skip"
        return "fail"

    def status_from_case(case: dict) -> str:
        status_field = str(case.get("status", "")).upper()
        result_field = str(case.get("result", "")).upper()
        if status_field in {"DISABLED", "NOTRUN"}:
            return "skip"
        if case.get("disabled"):
            return "skip"
        if result_field in {"SKIPPED", "SUPPRESSED", "NOTRUN"}:
            return "skip"
        if "skipped" in case and case.get("skipped"):
            return "skip"

        failures = case.get("failures")
        errors = case.get("errors")
        if isinstance(failures, (list, dict, str)) and failures:
            return "fail"
        if isinstance(errors, (list, dict, str)) and errors:
            return "fail"
        if status_field in {"FAILED", "FAIL", "ERROR"}:
            return "fail"
        if result_field in {"FAILED", "FAILURE", "ERROR", "CRASHED"}:
            return "fail"

        return "pass"

    def record_case(name: str | None, classname: str | None, status: str) -> None:
        if not name and classname:
            test_name = classname
        elif name and classname and name != classname:
            test_name = f"{classname}.{name}"
        else:
            test_name = name or ""
        if test_name:
            results[test_name] = status

    def traverse_json(obj, current_suite: str | None = None):
        if isinstance(obj, list):
            for item in obj:
                traverse_json(item, current_suite)
            return
        if not isinstance(obj, dict):
            return

        name = obj.get("name")
        classname = obj.get("classname")
        child_keys = [k for k in ("testsuites", "testsuite", "testcase") if k in obj]
        is_leaf = not child_keys

        # If this dict looks like a testcase or is a leaf with a name, record it.
        if name and is_leaf:
            suite_name = classname or current_suite
            record_case(name, suite_name, status_from_case(obj))

        # Update suite context if this is a suite
        suite_name = current_suite
        if child_keys and name:
            suite_name = f"{current_suite}.{name}" if current_suite else name

        for key in child_keys:
            traverse_json(obj[key], suite_name)

    # Parse multiple JSON blobs in the log.
    decoder = json.JSONDecoder()
    idx = 0
    while idx < len(log):
        start = log.find("{", idx)
        if start == -1:
            break
        try:
            data, offset = decoder.raw_decode(log[start:])
            idx = start + offset
        except Exception:
            idx = start + 1
            continue
        if isinstance(data, dict) and any(k in data for k in ("testsuites", "testsuite", "testcase", "tests")):
            traverse_json(data)

    # Parse XML blocks (JUnit/TestNG)
    if "<testsuite" in log or "<testsuites" in log:
        xml_candidates = []
        xml_candidates += [m.start() for m in re.finditer(r"<testsuites[\s>]", log)]
        xml_candidates += [m.start() for m in re.finditer(r"<testsuite[\s>]", log)]
        for start in xml_candidates:
            fragment = log[start:]
            end = fragment.rfind("</testsuites>")
            if end != -1:
                frag = fragment[: end + len("</testsuites>")]
            else:
                end = fragment.rfind("</testsuite>")
                if end == -1:
                    continue
                frag = fragment[: end + len("</testsuite>")]
            try:
                root = ET.fromstring(frag)
            except Exception:
                continue

            def handle_xml(elem, suite_prefix=""):
                if elem.tag == "testsuite":
                    suite_name = elem.attrib.get("name") or suite_prefix
                    for child in elem:
                        handle_xml(child, suite_name)
                elif elem.tag == "testcase":
                    name = elem.attrib.get("name")
                    classname = elem.attrib.get("classname") or suite_prefix
                    status = "pass"
                    for child in elem:
                        tag = child.tag.lower()
                        if tag in {"failure", "error"}:
                            status = "fail"
                            break
                        if tag == "skipped":
                            status = "skip"
                    record_case(name, classname, status)
                else:
                    for child in elem:
                        handle_xml(child, suite_prefix)

            handle_xml(root)

    # Text parsing
    last_unittest = None

    for raw in log.splitlines():
        stripped = raw.strip()

        # GoogleTest text output
        m = re.match(r"^\[\s*RUN\s*\]\s+(\S+)", stripped)
        if m:
            continue
        m = re.match(r"^\[\s*(OK|FAILED|SKIPPED)\s*\]\s+(\S+)", stripped)
        if m:
            results[m.group(2)] = norm_status(m.group(1))
            continue

        # pytest verbose lines
        m = re.match(r"^(\S+::\S+.*?)\s+(PASSED|FAILED|SKIPPED|XFAIL|XPASS|ERROR)\b", stripped)
        if m:
            results[m.group(1)] = norm_status(m.group(2))
            continue
        # pytest summary lines: FAILED path::test
        m = re.match(r"^(FAILED|ERROR|SKIPPED|XFAIL|XPASS)\s+\[?\d*\]?\s*(\S+::\S+)", stripped)
        if m:
            results[m.group(2)] = norm_status(m.group(1))
            continue

        # unittest inline: test (module.Class) ... ok/FAIL
        m = re.match(r"^(\w[\w\.]*)\s+\(([^)]+)\)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped|xfail|expected failure)\b", stripped, re.IGNORECASE)
        if m:
            results[f"{m.group(2)}.{m.group(1)}"] = norm_status(m.group(3))
            last_unittest = None
            continue

        # unittest start line: test (module.Class)
        m = re.match(r"^(\w[\w\.]*)\s+\(([^)]+)\)\s*$", stripped)
        if m:
            last_unittest = f"{m.group(2)}.{m.group(1)}"
            continue

        # unittest continuation
        m = re.match(r"^(?:\.\.\.\s*)?(ok|FAIL|ERROR|skipped|xfail|expected failure)\b", stripped, re.IGNORECASE)
        if m and last_unittest:
            results[last_unittest] = norm_status(m.group(1))
            last_unittest = None
            continue

        # unittest without class: test_name ... ok
        m = re.match(r"^(\w[\w\.]*)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped|xfail|expected failure)\b", stripped, re.IGNORECASE)
        if m:
            results[m.group(1)] = norm_status(m.group(2))
            continue

        # nose/unittest failure summary: FAIL: test (module.Class)
        m = re.match(r"^(FAIL|ERROR):\s+(\w[\w\.]*)\s+\(([^)]+)\)", stripped)
        if m:
            results[f"{m.group(3)}.{m.group(2)}"] = norm_status(m.group(1))
            continue

        # Go test
        m = re.match(r"^---\s+(PASS|FAIL|SKIP):\s+(\S+)", stripped)
        if m:
            results[m.group(2)] = norm_status(m.group(1))
            continue

        # TAP
        m = re.match(r"^(not ok|ok)\s+\d*\s*-?\s*(.*)", stripped, re.IGNORECASE)
        if m:
            name = m.group(2).strip() or f"tap_{m.group(1)}"
            status = "pass" if m.group(1).lower() == "ok" else "fail"
            if "# skip" in stripped.lower():
                status = "skip"
            results[name] = status
            continue

        # Jest-like symbols
        m = re.match(r"^[\s]*([✓✕○])\s+(.+)", stripped)
        if m:
            symbol = m.group(1)
            name = m.group(2).strip()
            results[name] = "pass" if symbol == "✓" else "skip" if symbol == "○" else "fail"
            continue

        # Simple "PASS: testname" or "FAIL: testname"
        m = re.match(r"^(PASS|FAIL|SKIP)\s*[:\-]\s*(.+)", stripped, re.IGNORECASE)
        if m:
            results[m.group(2).strip()] = norm_status(m.group(1))
            continue

    return results
